package com.riverguard.v2;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.riverguard.v2.PhoneValidation.*;
public class SharedSignalParityTest {
    private JSONObject fixture()throws Exception {Path directory=Paths.get(System.getProperty("user.dir")).toAbsolutePath();while(directory!=null){Path path=directory.resolve("v2/tests/fixtures/signal-repairs.json");if(Files.isRegularFile(path))return object(new String(Files.readAllBytes(path),StandardCharsets.UTF_8));directory=directory.getParent();}throw new IllegalStateException("Shared signal fixtures are missing.");}
    private List<String> names(JSONArray values,String key){List<String> result=new ArrayList<>();for(int i=0;i<values.length();i++)result.add(key==null?values.optString(i):values.optJSONObject(i).optString(key));Collections.sort(result);return result;}
    @Test public void snapshotVectorsMatch()throws Exception{JSONObject fixture=fixture();JSONArray cases=fixture.optJSONArray("cases");long now=fixture.optLong("now");for(int i=0;i<cases.length();i++){JSONObject c=cases.optJSONObject(i),expected=c.optJSONObject("expected"),result=SignalEvaluator.evaluate(c.optJSONArray("records"),c.optJSONObject("watch"),now);assertEquals(c.optString("name"),expected.optBoolean("fresh"),result.optBoolean("fresh"));assertEquals(names(expected.optJSONArray("activeKinds"),null),names(result.optJSONArray("signals"),"kind"));JSONObject evidence=expected.optJSONObject("evidence");java.util.Iterator<String> keys=evidence.keys();while(keys.hasNext()){String key=keys.next();assertEquals(c.optString("name")+":"+key,evidence.optString(key),result.optJSONObject("evidence").optString(key));}assertEquals(expected.isNull("rate"),result.isNull("rate"));if(!expected.isNull("rate"))assertEquals(expected.optDouble("rate"),result.optDouble("rate"),.00001);SignalEvaluator.Reading reading=new SignalEvaluator.Reading(c.optJSONArray("records").optJSONObject(0),now);for(int j=0;j<4;j++){if(expected.optJSONArray("values").isNull(j))assertNull(reading.values[j]);else assertEquals(expected.optJSONArray("values").optDouble(j),reading.values[j],.00001);}}}
    @Test public void ledgerVectorsMatch()throws Exception{JSONObject fixture=fixture();JSONArray cases=fixture.optJSONArray("cases"),sequences=fixture.optJSONArray("sequences");for(int i=0;i<sequences.length();i++){JSONObject sequence=sequences.optJSONObject(i),state=null;JSONArray steps=sequence.optJSONArray("steps");for(int j=0;j<steps.length();j++){JSONObject step=steps.optJSONObject(j),c=null;for(int k=0;k<cases.length();k++)if(cases.optJSONObject(k).optString("name").equals(step.optString("case")))c=copy(cases.optJSONObject(k));assertNotNull(c);JSONArray rows=c.optJSONArray("records");put(rows.optJSONObject(0).optJSONObject("payload"),"sample_id","step-"+j);JSONObject evaluation=SignalEvaluator.evaluate(rows,c.optJSONObject("watch"),fixture.optLong("now"));put(evaluation,"watchRevision",step.optInt("watchRevision"));put(evaluation,"watchSettings",c.optJSONObject("watch"));put(evaluation,"segment",evaluation.optInt("calibrationRevision")+":"+step.optInt("watchRevision"));JSONObject change=AlertLedger.apply(state,evaluation,fixture.optLong("now"));state=change.optJSONObject("state");JSONArray events=change.optJSONArray("events"),expected=step.optJSONArray("expectedEvents");assertEquals(sequence.optString("name")+" step"+j,expected.length(),events.length());for(int k=0;k<events.length();k++){assertEquals(expected.optJSONArray(k).optString(0),events.optJSONObject(k).optString("kind"));assertEquals(expected.optJSONArray(k).optString(1),events.optJSONObject(k).optString("phase"));}}List<String> active=new ArrayList<>();JSONObject conditions=state.optJSONObject("conditions");java.util.Iterator<String> keys=conditions.keys();while(keys.hasNext()){String key=keys.next();if(conditions.optJSONObject(key).optBoolean("active"))active.add(key);}Collections.sort(active);assertEquals(names(sequence.optJSONArray("finalActive"),null),active);}}
}
